-- 067: LeSourdsville Lake Amusement Park (Monroe, OH; later Americana),
-- from RCDB via Carter's screenshots and pin, 2026-10-18. Three coasters:
--   Serpent (SDC Galaxi, 1989-2002): the second stop of the travelling
--     Galaxi, so it joins 065/066's set (home Serpent at Niagara).
--   Jack Rabbit (kiddie, 1955-68): RCDB cannot tell whether Miler, Schiff or
--     Molina built it, so no maker.
--   Little Dipper (Allan Herschell, built 1956, closed 2002, opening year
--     unknown): moved to Sluggers & Putters (066), so linked, home there.
-- Every statement is guarded, so a second run is a no-op.

INSERT INTO parks (name, lat, lon, region) SELECT 'LeSourdsville Lake Amusement Park', 39.44315275235862, -84.43275396654404, 'Ohio, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'LeSourdsville Lake Amusement Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Serpent', 'LeSourdsville Lake Amusement Park', 'Steel', 'SDC', 'SDC Galaxi', 45, NULL, 1919, 0, 110, 1, 1989, '1989', 'year', '2002', 'year' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'LeSourdsville Lake Amusement Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Serpent' AND park = 'LeSourdsville Lake Amusement Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Jack Rabbit', 'LeSourdsville Lake Amusement Park', 'Steel', NULL, 'Kiddie', NULL, NULL, NULL, 0, NULL, 1, 1955, '1955', 'year', '1968', 'year' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'LeSourdsville Lake Amusement Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Jack Rabbit' AND park = 'LeSourdsville Lake Amusement Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Little Dipper', 'LeSourdsville Lake Amusement Park', 'Steel', 'Allan Herschell', 'Allan Herschell Little Dipper', NULL, NULL, NULL, 0, NULL, 1, NULL, NULL, NULL, '2002', 'year' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'LeSourdsville Lake Amusement Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Little Dipper' AND park = 'LeSourdsville Lake Amusement Park');
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT x.id, h.id FROM coasters h, coasters x WHERE h.name = 'Serpent' AND h.park = 'Niagara Amusement Park & Splash World' AND x.name = 'Serpent' AND x.park = 'LeSourdsville Lake Amusement Park';
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT x.id, h.id FROM coasters h, coasters x WHERE h.name = 'Little Dipper' AND h.park = 'Sluggers & Putters' AND (x.id = h.id OR (x.name = 'Little Dipper' AND x.park = 'LeSourdsville Lake Amusement Park'));
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.park = 'LeSourdsville Lake Amusement Park' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND a.subject = c.name AND json_extract(a.detail, '$.park') = c.park);
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'same_ride_set', h.name, (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id), json_object('ride', h.id, 'at', (SELECT json_group_array(json_object('id', c.id, 'park', c.park, 'name', c.name)) FROM coasters c JOIN same_ride s ON s.coaster = c.id WHERE s.ride = h.id), 'via', '067') FROM coasters h WHERE ((h.name = 'Serpent' AND h.park = 'Niagara Amusement Park & Splash World') OR (h.name = 'Little Dipper' AND h.park = 'Sluggers & Putters')) AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'same_ride_set' AND json_extract(a.detail, '$.ride') = h.id AND a.detail LIKE '%"via":"067"%');
